def find_rectangles(arr):
    """Find all rectangular outlines in the grid"""
    rectangles = []
    for r1 in range(arr.shape[0]):
        for r2 in range(r1 + 3, arr.shape[0]):  # Need at least 3 rows
            for c1 in range(arr.shape[1]):
                for c2 in range(c1 + 3, arr.shape[1]):  # Need at least 3 cols
