                    border_pixels = 0
                    interior_pixels = 0

                    # Check top/bottom edges
                    for c in range(c1, c2 + 1):
                        if arr[r1, c] == 1:
                            border_pixels += 1
                        if arr[r2, c] == 1:
                            border_pixels += 1

                        # Check interior
                        if interior_r := r2 - r1 - 1:
                            for rc in range(interior_r):
