    - Left padding: cols 0 to max_c-1 for rows 0 to max_r
    - Right padding: col max_c+1 for rows 0 to max_r
    - Bottom padding: row max_r+1 for cols 0 to max_c
    """
    h, w = arr.shape
    result = np.zeros((h, w), dtype=int)

    # Step 1: Find structures using 8-connectivity
    visited = set()
    structures = []

    for r in range(h):
        for c in range(w):
            if arr[r, c] == 1 and (r, c) not in visited:
                struct_cells = []
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    struct_cells.append((cr, cc))
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w and arr[nr, nc] == 1 and (nr, nc) not in visited:
                                stack.append((nr, nc))

                if len(struct_cells) >= 5:
                    rows = [cr for cr, cc in struct_cells]
                    cols = [cc for cr, cc in struct_cells]
                    min_r, max_r = min(rows), max(rows)
                    min_c, max_c = min(cols), max(cols)
                    structures.append((min_r, max_r, min_c, max_c))

