    for min_r, max_r, min_c, max_c in structures:
        for r in range(min_r + 1, max_r):
            for c in range(min_c + 1, max_c):
                has_diag_1 = False
                for dr in [-1, 1]:
                    for dc in [-1, 1]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and arr[nr, nc] == 1:
                            has_diag_1 = True
                            break
                    if has_diag_1:
                        break
                if has_diag_1 and arr[r, c] == 0:
                    result[r, c] = 3

    # Step 4: Add padding with 2s
    for min_r, max_r, min_c, max_c in structures:
        # Left padding: cols 0 to max_c-1 for rows 0 to max_r
        for r in range(min(max_r, h-1), max(-1, min_r - 1) - 1, -1):
            # Actually rows 0 to max_r inclusive
            pass
        for r in range(min_r, max_r + 1):
            for c in range(0, max_c):  # cols 0 to max_c-1
                if arr[r, c] == 0:
                    result[r, c] = 2

        # Right padding: col max_c+1 for rows 0 to max_r
        for r in range(min_r, max_r + 1):
            if max_c + 1 < w:
                if arr[r, max_c + 1] == 0:
                    result[r, max_c + 1] = 2

        # Bottom padding: row max_r+1 for cols 0 to max_c
        if max_r + 1 < h:
            for c in range(0, max_c + 1):  # cols 0 to max_c
                if arr[max_r + 1, c] == 0:
                    result[max_r + 1, c] = 2

    return result

