        for c in range(w):
            if arr[r, c] == 1 and (r, c) not in visited:
                struct_cells = []
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    struct_cells.append((cr, cc))
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w and arr[nr, nc] == 1 and (nr, nc) not in visited:
                                stack.append((nr, nc))

                if len(struct_cells) >= 5:
                    rows = [cr for cr, cc in struct_cells]
                    cols = [cc for cr, cc in struct_cells]
                    min_r, max_r = min(rows), max(rows)
                    min_c, max_c = min(cols), max(cols)
                    structures.append((min_r, max_r, min_c, max_c))

    # Step 2: Copy original 1s to result
    for r in range(h):
        for c in range(w):
            if arr[r, c] == 1:
                result[r, c] = 1

    # Step 3: Fill interior (cells that are 0 in INPUT AND have diagonal 1 in INPUT)
    for min_r, max_r, min_c, max_c in structures:
        for r in range(min_r + 1, max_r):
            for c in range(min_c + 1, max_c):
                # Check if cell is 0 in input
                if arr[r, c] == 0:
                    # Check for diagonal 1 in INPUT
                    has_diag_1 = False
                    for dr in [-1, 1]:
                        for dc in [-1, 1]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < h and 0 <= nc < w and arr[nr, nc] == 1:
                                has_diag_1 = True
                                break
                        if has_diag_1:
                            break
                    if has_diag_1:
                        result[r, c] = 3

    # Step 4: Add padding with 2s
    for min_r, max_r, min_c, max_c in structures:
        # Right padding: column max_c+1 for structure rows
        right_col = max_c + 1
        if 0 < right_col < w:
            for r in range(min_r, max_r + 1):
                if arr[r, right_col] == 0 and result[r, right_col] != 1:
                    result[r, right_col] = 2

        # Bottom padding: row max_r+1 for cols 0 to max_c+1
        bottom_row = max_r + 1
        if 0 < bottom_row < h:
            for c in range(min_c, min(max_c + 2, w)):  # Start from min_c, go to max_c+1
                if arr[bottom_row, c] == 0 and result[bottom_row, c] != 1:
                    result[bottom_row, c] = 2

        # Left padding: cols 0 to min_c-1 for structure rows
        if min_c > 0:
            for r in range(min_r, max_r + 1):
                for c in range(0, min_c):
                    if arr[r, c] == 0 and result[r, c] != 1:
                        result[r, c] = 2

        # Special: if min_r == 0 and min_c > 0, extend left padding in row 0
        # to before first 1 is found in row 0
        if min_r == 0 and min_c > 0:
            first_1_col = min_c
            for c in range(min_c, w):
                if arr[0, c] == 1:
